{"ts":"2026-09-20T12:03:52.666+03:00","v":"1","level":"DEBUG","logger":"org.hibernate.SQL","thread":"Test worker","msg":"SELECT a.*
FROM assignments a
JOIN semesters existing_semester ON existing_semester.id = a.semester_id
WHERE a.teacher_id = ?
  AND a.subject_id = ?
  AND a.group_id = ?
  AND a.semester_id = ?
  AND a.lesson_type = CAST(? AS subject_type)
  AND daterange(
        a.valid_from,
        COALESCE(a.valid_until_exclusive, existing_semester.date_to + 1),
        '[)'
      ) && daterange(
        CAST(? AS date),
        COALESCE(CAST(? AS date), existing_semester.date_to + 1),
        '[)'
      )
LIMIT 1
","traceId":"cf0d3c1685c0b947d26cbbeea761c655","service":"academic-service"}
